-- Objective: Persist universal broadcast iteration context and continuity without changing audio-frame delivery.

alter table "public"."episodes"
  add column if not exists "raw_content" text,
  add column if not exists "summary" text,
  add column if not exists "closing_sentence" text,
  add column if not exists "generated_at" timestamptz;

create table if not exists "public"."broadcast_memories" (
  "id" bigint generated by default as identity primary key,
  "external_id" text not null unique,
  "content" text not null,
  "category" text,
  "active" boolean not null default true,
  "display_order" integer not null default 0,
  "metadata" jsonb not null default '{}',
  "created_at" timestamptz not null default now(),
  "updated_at" timestamptz not null default now()
);

create index if not exists "broadcast_memories_active_order_idx"
  on "public"."broadcast_memories" ("active", "display_order", "id");

alter table "public"."broadcast_memories" enable row level security;

create table if not exists "public"."broadcast_iterations" (
  "id" uuid primary key default gen_random_uuid(),
  "generation_key" text not null unique,
  "sequence_number" bigint generated by default as identity unique,
  "predecessor_iteration_id" uuid references "public"."broadcast_iterations"("id"),
  "episode_id" bigint unique references "public"."episodes"("id"),
  "generation_status" text not null default 'PENDING'
    check ("generation_status" in ('PENDING', 'COMPLETED', 'FAILED')),
  "playback_status" text not null default 'NOT_PLAYED'
    check ("playback_status" in ('NOT_PLAYED', 'PLAYING', 'PLAYED', 'SKIPPED')),
  "response_hash" text,
  "generated_at" timestamptz,
  "played_at" timestamptz,
  "created_at" timestamptz not null default now(),
  "updated_at" timestamptz not null default now(),
  check (
    ("generation_status" = 'COMPLETED' and "episode_id" is not null and "response_hash" is not null)
    or ("generation_status" <> 'COMPLETED' and "episode_id" is null)
  )
);

create index if not exists "broadcast_iterations_generation_history_idx"
  on "public"."broadcast_iterations" ("generation_status", "sequence_number" desc);
create index if not exists "broadcast_iterations_playback_history_idx"
  on "public"."broadcast_iterations" ("playback_status", "sequence_number" desc);

alter table "public"."broadcast_iterations" enable row level security;

create table if not exists "public"."broadcast_iteration_songs" (
  "iteration_id" uuid not null references "public"."broadcast_iterations"("id"),
  "song_id" bigint not null references "public"."songs"("id"),
  "position" integer not null check ("position" > 0),
  "created_at" timestamptz not null default now(),
  primary key ("iteration_id", "song_id"),
  unique ("iteration_id", "position")
);

create index if not exists "broadcast_iteration_songs_song_idx"
  on "public"."broadcast_iteration_songs" ("song_id");

alter table "public"."broadcast_iteration_songs" enable row level security;

create table if not exists "public"."broadcast_iteration_memories" (
  "iteration_id" uuid not null references "public"."broadcast_iterations"("id"),
  "memory_id" bigint not null references "public"."broadcast_memories"("id"),
  "position" integer not null check ("position" > 0),
  "created_at" timestamptz not null default now(),
  primary key ("iteration_id", "memory_id"),
  unique ("iteration_id", "position")
);

create index if not exists "broadcast_iteration_memories_memory_idx"
  on "public"."broadcast_iteration_memories" ("memory_id");

alter table "public"."broadcast_iteration_memories" enable row level security;

create table if not exists "public"."broadcast_continuity_state" (
  "singleton" boolean primary key default true check ("singleton"),
  "last_completed_iteration_id" uuid references "public"."broadcast_iterations"("id"),
  "last_played_iteration_id" uuid references "public"."broadcast_iterations"("id"),
  "rolling_summary" text,
  "last_closing_sentence" text,
  "updated_at" timestamptz not null default now()
);

alter table "public"."broadcast_continuity_state" enable row level security;

create or replace function "public"."create_broadcast_iteration"(
  p_generation_key text,
  p_song_ids bigint[] default '{}'::bigint[],
  p_memory_ids bigint[] default '{}'::bigint[]
)
returns "public"."broadcast_iterations"
language plpgsql
set search_path = public
as $$
declare
  v_iteration "public"."broadcast_iterations"%rowtype;
  v_predecessor_id uuid;
  v_existing_song_ids bigint[];
  v_existing_memory_ids bigint[];
begin
  if nullif(btrim(p_generation_key), '') is null then
    raise exception 'generation_key is required';
  end if;

  -- This is a universal broadcast: one open manifest at a time gives every
  -- iteration a stable, unambiguous predecessor while still permitting a
  -- completed episode to wait independently for playback.
  perform pg_advisory_xact_lock(hashtext('broadcast_iteration_creation'));

  if exists (
    select 1 from unnest(coalesce(p_song_ids, '{}'::bigint[])) as selected(song_id)
    group by selected.song_id having count(*) > 1
  ) then
    raise exception 'Selected songs must not contain duplicates';
  end if;

  if exists (
    select 1 from unnest(coalesce(p_memory_ids, '{}'::bigint[])) as selected(memory_id)
    group by selected.memory_id having count(*) > 1
  ) then
    raise exception 'Selected memories must not contain duplicates';
  end if;

  select * into v_iteration
    from "public"."broadcast_iterations"
   where "generation_key" = p_generation_key
   for update;

  if found then
    select coalesce(array_agg("song_id" order by "position"), '{}'::bigint[])
      into v_existing_song_ids
      from "public"."broadcast_iteration_songs"
     where "iteration_id" = v_iteration."id";
    select coalesce(array_agg("memory_id" order by "position"), '{}'::bigint[])
      into v_existing_memory_ids
      from "public"."broadcast_iteration_memories"
     where "iteration_id" = v_iteration."id";

    if v_existing_song_ids is distinct from coalesce(p_song_ids, '{}'::bigint[])
       or v_existing_memory_ids is distinct from coalesce(p_memory_ids, '{}'::bigint[]) then
      raise exception 'generation_key was already used with different curated inputs';
    end if;
    return v_iteration;
  end if;

  if exists (
    select 1 from "public"."broadcast_iterations" where "generation_status" = 'PENDING'
  ) then
    raise exception 'A broadcast iteration is already pending completion';
  end if;

  if exists (
    select 1
      from unnest(coalesce(p_song_ids, '{}'::bigint[])) as selected(song_id)
      left join "public"."songs" s on s."id" = selected.song_id
     where s."id" is null or not s."enabled"
  ) then
    raise exception 'Selected songs must exist and be enabled';
  end if;

  if exists (
    select 1
      from unnest(coalesce(p_memory_ids, '{}'::bigint[])) as selected(memory_id)
      left join "public"."broadcast_memories" m on m."id" = selected.memory_id
     where m."id" is null or not m."active"
  ) then
    raise exception 'Selected memories must exist and be active';
  end if;

  select "id" into v_predecessor_id
    from "public"."broadcast_iterations"
   where "generation_status" = 'COMPLETED'
   order by "sequence_number" desc
   limit 1;

  insert into "public"."broadcast_iterations" ("generation_key", "predecessor_iteration_id")
  values (p_generation_key, v_predecessor_id)
  returning * into v_iteration;

  insert into "public"."broadcast_iteration_songs" ("iteration_id", "song_id", "position")
  select v_iteration."id", selected.song_id, selected.position::integer
    from unnest(coalesce(p_song_ids, '{}'::bigint[])) with ordinality as selected(song_id, position);

  insert into "public"."broadcast_iteration_memories" ("iteration_id", "memory_id", "position")
  select v_iteration."id", selected.memory_id, selected.position::integer
    from unnest(coalesce(p_memory_ids, '{}'::bigint[])) with ordinality as selected(memory_id, position);

  return v_iteration;
end;
$$;

create or replace function "public"."get_broadcast_context"(
  p_iteration_id uuid,
  p_history_limit integer default 5
)
returns jsonb
language plpgsql
stable
set search_path = public
as $$
declare
  v_iteration "public"."broadcast_iterations"%rowtype;
  v_predecessor_sequence bigint;
  v_previous_episode jsonb;
  v_recent_episodes jsonb;
  v_selected_songs jsonb;
  v_selected_memories jsonb;
  v_continuity_state jsonb;
begin
  if p_history_limit is null or p_history_limit < 1 or p_history_limit > 20 then
    raise exception 'history limit must be between 1 and 20';
  end if;

  select * into v_iteration from "public"."broadcast_iterations" where "id" = p_iteration_id;
  if not found then
    raise exception 'Broadcast iteration was not found';
  end if;

  select "sequence_number" into v_predecessor_sequence
    from "public"."broadcast_iterations"
   where "id" = v_iteration."predecessor_iteration_id";

  select jsonb_build_object(
    'iteration_id', predecessor."id",
    'sequence_number', predecessor."sequence_number",
    'episode_id', episode."id",
    'summary', episode."summary",
    'closing_sentence', episode."closing_sentence",
    'generation_status', predecessor."generation_status",
    'playback_status', predecessor."playback_status"
  ) into v_previous_episode
    from "public"."broadcast_iterations" predecessor
    join "public"."episodes" episode on episode."id" = predecessor."episode_id"
   where predecessor."id" = v_iteration."predecessor_iteration_id";

  select coalesce(jsonb_agg(history.item order by history.sequence_number asc), '[]'::jsonb)
    into v_recent_episodes
    from (
      select candidate."sequence_number", jsonb_build_object(
        'iteration_id', candidate."id",
        'sequence_number', candidate."sequence_number",
        'episode_id', episode."id",
        'summary', episode."summary",
        'closing_sentence', episode."closing_sentence",
        'generation_status', candidate."generation_status",
        'playback_status', candidate."playback_status",
        'songs', coalesce((
          select jsonb_agg(jsonb_build_object(
            'id', song."id", 'external_id', song."external_id", 'title', song."title", 'artist', song."artist"
          ) order by iteration_song."position")
          from "public"."broadcast_iteration_songs" iteration_song
          join "public"."songs" song on song."id" = iteration_song."song_id"
         where iteration_song."iteration_id" = candidate."id"
        ), '[]'::jsonb),
        'memory_ids', coalesce((
          select jsonb_agg(iteration_memory."memory_id" order by iteration_memory."position")
          from "public"."broadcast_iteration_memories" iteration_memory
         where iteration_memory."iteration_id" = candidate."id"
        ), '[]'::jsonb)
      ) as item
        from (
          select * from "public"."broadcast_iterations"
           where "generation_status" = 'COMPLETED'
             and (v_predecessor_sequence is null or "sequence_number" <= v_predecessor_sequence)
           order by "sequence_number" desc
           limit p_history_limit
        ) candidate
        join "public"."episodes" episode on episode."id" = candidate."episode_id"
    ) history;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', song."id", 'external_id', song."external_id", 'title', song."title", 'artist', song."artist",
    'album', song."album", 'language', song."language", 'genre', song."genre", 'mood', song."mood",
    'tags', song."tags", 'relationship_tags', song."relationship_tags"
  ) order by iteration_song."position"), '[]'::jsonb)
    into v_selected_songs
    from "public"."broadcast_iteration_songs" iteration_song
    join "public"."songs" song on song."id" = iteration_song."song_id"
   where iteration_song."iteration_id" = v_iteration."id";

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', memory."id", 'external_id', memory."external_id", 'content', memory."content", 'category', memory."category"
  ) order by iteration_memory."position"), '[]'::jsonb)
    into v_selected_memories
    from "public"."broadcast_iteration_memories" iteration_memory
    join "public"."broadcast_memories" memory on memory."id" = iteration_memory."memory_id"
   where iteration_memory."iteration_id" = v_iteration."id";

  select jsonb_build_object(
    'rolling_summary', state."rolling_summary",
    'last_completed_iteration_id', state."last_completed_iteration_id",
    'last_played_iteration_id', state."last_played_iteration_id",
    'last_closing_sentence', state."last_closing_sentence"
  ) into v_continuity_state
    from "public"."broadcast_continuity_state" state
   where state."singleton" = true;

  return jsonb_build_object(
    'iteration_id', v_iteration."id",
    'generation_key', v_iteration."generation_key",
    'sequence_number', v_iteration."sequence_number",
    'generation_status', v_iteration."generation_status",
    'playback_status', v_iteration."playback_status",
    'previous_episode', v_previous_episode,
    'recent_episodes', v_recent_episodes,
    'selected_songs', v_selected_songs,
    'curated_memories', v_selected_memories,
    'continuity_state', coalesce(v_continuity_state, jsonb_build_object(
      'rolling_summary', null,
      'last_completed_iteration_id', null,
      'last_played_iteration_id', null,
      'last_closing_sentence', null
    ))
  );
end;
$$;

create or replace function "public"."complete_broadcast_iteration"(
  p_iteration_id uuid,
  p_title text,
  p_language text,
  p_raw_content text,
  p_summary text,
  p_closing_sentence text,
  p_response_hash text
)
returns "public"."broadcast_iterations"
language plpgsql
set search_path = public
as $$
declare
  v_iteration "public"."broadcast_iterations"%rowtype;
  v_episode_id bigint;
  v_last_completed_id uuid;
begin
  if nullif(btrim(p_title), '') is null or nullif(btrim(p_language), '') is null
     or nullif(btrim(p_raw_content), '') is null or nullif(btrim(p_response_hash), '') is null then
    raise exception 'title, language, raw content, and response hash are required';
  end if;

  perform pg_advisory_xact_lock(hashtext('broadcast_continuity'));

  select * into v_iteration
    from "public"."broadcast_iterations"
   where "id" = p_iteration_id
   for update;
  if not found then
    raise exception 'Broadcast iteration was not found';
  end if;

  if v_iteration."generation_status" = 'COMPLETED' then
    if v_iteration."response_hash" = p_response_hash then
      return v_iteration;
    end if;
    raise exception 'Broadcast iteration was already completed with a different response';
  end if;

  if v_iteration."generation_status" <> 'PENDING' then
    raise exception 'Only pending broadcast iterations can be completed';
  end if;

  if exists (
    select 1 from "public"."broadcast_iterations"
     where "generation_status" = 'PENDING'
       and "sequence_number" < v_iteration."sequence_number"
  ) then
    raise exception 'Earlier broadcast iterations must complete first';
  end if;

  select "last_completed_iteration_id" into v_last_completed_id
    from "public"."broadcast_continuity_state"
   where "singleton" = true
   for update;

  if v_iteration."predecessor_iteration_id" is distinct from v_last_completed_id then
    raise exception 'Broadcast predecessor no longer matches continuity state';
  end if;

  insert into "public"."episodes" (
    "external_id", "title", "language", "metadata", "raw_content", "summary", "closing_sentence", "generated_at"
  ) values (
    'broadcast-' || v_iteration."id"::text,
    p_title,
    p_language,
    jsonb_build_object('source', 'broadcast_context_manager', 'iteration_id', v_iteration."id"),
    p_raw_content,
    p_summary,
    p_closing_sentence,
    now()
  ) returning "id" into v_episode_id;

  update "public"."broadcast_iterations"
     set "episode_id" = v_episode_id,
         "generation_status" = 'COMPLETED',
         "response_hash" = p_response_hash,
         "generated_at" = now(),
         "updated_at" = now()
   where "id" = v_iteration."id"
   returning * into v_iteration;

  insert into "public"."broadcast_continuity_state" (
    "singleton", "last_completed_iteration_id", "rolling_summary", "last_closing_sentence", "updated_at"
  ) values (
    true, v_iteration."id", p_summary, p_closing_sentence, now()
  )
  on conflict ("singleton") do update
     set "last_completed_iteration_id" = excluded."last_completed_iteration_id",
         "rolling_summary" = excluded."rolling_summary",
         "last_closing_sentence" = excluded."last_closing_sentence",
         "updated_at" = excluded."updated_at";

  return v_iteration;
end;
$$;

create or replace function "public"."mark_broadcast_iteration_played"(
  p_iteration_id uuid
)
returns "public"."broadcast_iterations"
language plpgsql
set search_path = public
as $$
declare
  v_iteration "public"."broadcast_iterations"%rowtype;
begin
  select * into v_iteration
    from "public"."broadcast_iterations"
   where "id" = p_iteration_id
   for update;
  if not found then
    raise exception 'Broadcast iteration was not found';
  end if;
  if v_iteration."generation_status" <> 'COMPLETED' then
    raise exception 'Only completed broadcast iterations can be marked played';
  end if;

  update "public"."broadcast_iterations"
     set "playback_status" = 'PLAYED',
         "played_at" = coalesce("played_at", now()),
         "updated_at" = now()
   where "id" = v_iteration."id"
   returning * into v_iteration;

  insert into "public"."broadcast_continuity_state" ("singleton", "last_played_iteration_id", "updated_at")
  values (true, v_iteration."id", now())
  on conflict ("singleton") do update
     set "last_played_iteration_id" = case
           when (select "sequence_number" from "public"."broadcast_iterations" where "id" = "broadcast_continuity_state"."last_played_iteration_id")
                > v_iteration."sequence_number"
             then "broadcast_continuity_state"."last_played_iteration_id"
           else excluded."last_played_iteration_id"
         end,
         "updated_at" = excluded."updated_at";

  return v_iteration;
end;
$$;
